import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <int THREADS, int BLOCK_M, int BLOCK_K>
__global__ void matvec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K)
{
  int block_row_start = blockIdx.x * BLOCK_M;
  int tid = threadIdx.x;
  extern __shared__ float sB[];
  float sum[BLOCK_M];
  #pragma unroll
  for (int r = 0; r < BLOCK_M; r++) sum[r] = 0.0f;
  for (int k0 = 0; k0 < K; k0 += BLOCK_K) {
    int chunk = (K - k0 < BLOCK_K) ? (K - k0) : BLOCK_K;
    // Cooperative, coalesced staging of the shared B chunk into shared memory.
    // This chunk is reused by BLOCK_M rows of A, cutting redundant global
    // memory traffic for B by a factor of BLOCK_M compared to one-row-per-block.
    for (int i = tid; i < chunk; i += THREADS) {
      sB[i] = B[k0 + i];
    }
    __syncthreads();
    for (int i = tid; i < chunk; i += THREADS) {
      float bval = sB[i];
      int k = k0 + i;
      #pragma unroll
      for (int r = 0; r < BLOCK_M; r++) {
        int row = block_row_start + r;
        if (row < M) {
          sum[r] += A[(size_t)row * K + k] * bval;
        }
      }
    }
    __syncthreads();
  }
  int lane = tid & 31;
  int wid  = tid >> 5;
  __shared__ float shared_reduce[BLOCK_M][THREADS / 32];
  #pragma unroll
  for (int r = 0; r < BLOCK_M; r++) {
    float v = sum[r];
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      v += __shfl_down_sync(0xffffffff, v, offset);
    }
    if (lane == 0) shared_reduce[r][wid] = v;
  }
  __syncthreads();
  if (wid == 0) {
    #pragma unroll
    for (int r = 0; r < BLOCK_M; r++) {
      float v = (lane < (THREADS / 32)) ? shared_reduce[r][lane] : 0.0f;
      #pragma unroll
      for (int offset = 16; offset > 0; offset >>= 1) {
        v += __shfl_down_sync(0xffffffff, v, offset);
      }
      if (lane == 0) {
        int row = block_row_start + r;
        if (row < M) {
          C[row] = v;
        }
      }
    }
  }
}
torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  auto B_flat = B.reshape({-1});
  TORCH_CHECK(B_flat.numel() == K, "B must have K elements");
  auto A_c = A.contiguous();
  auto B_c = B_flat.contiguous();
  auto C = torch::empty({M, 1}, A.options());
  constexpr int THREADS = 256;
  constexpr int BLOCK_M = 4;
  constexpr int BLOCK_K = 1024;
  dim3 block(THREADS);
  dim3 grid((unsigned)((M + BLOCK_M - 1) / BLOCK_M));
  size_t smem_bytes = BLOCK_K * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  matvec_kernel<THREADS, BLOCK_M, BLOCK_K><<<grid, block, smem_bytes, stream>>>(
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>(),
      M, K
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "matvec_kernel launch failed: ", cudaGetErrorString(err));
  return C;
}
"""

matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["matvec_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom
    CuTe-based CUDA kernel. Each CUDA block computes one output element
    (dot product of a row of A with B) using vectorized float4 loads
    and a two-stage (warp + block) reduction.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matvec_forward(A, B)

